/** Shared K6 config — reads users.json generated by pnpm load:seed */

export const DEFAULT_BASE_URL = __ENV.BASE_URL || "http://127.0.0.1:4000";
export const DEFAULT_WEB_ORIGIN = __ENV.WEB_ORIGIN || "http://localhost:3000";

/**
 * Localhost + remote Supabase — relaxed targets.
 * Per-endpoint thresholds are too noisy under concurrent load; use global p95 only.
 */
export const localhostThresholds = {
  http_req_failed: ["rate<0.05"],
  http_req_duration: ["p(95)<10000"]
};

/** Stricter targets for staging / production-like environments. */
export const productionThresholds = {
  http_req_failed: ["rate<0.01"],
  http_req_duration: ["p(95)<2000"]
};

export function resolveThresholds() {
  if (__ENV.THRESHOLD_PROFILE === "production") {
    return productionThresholds;
  }
  return localhostThresholds;
}

export function loadUsersData() {
  const raw = open("../data/users.json", "utf-8");
  return JSON.parse(raw);
}

export function jsonHeaders(webOrigin) {
  return {
    "Content-Type": "application/json",
    Origin: webOrigin
  };
}

export function summarizePass(summary, p95LimitMs, maxErrorRate = 0.05) {
  const failed = summary.metrics.http_req_failed?.values?.rate ?? 1;
  const p95 = summary.metrics.http_req_duration?.values?.["p(95)"] ?? Infinity;
  return failed < maxErrorRate && p95 < p95LimitMs;
}

/** Ramp-up intentionally finds breaking points — looser error budget. */
export const rampUpThresholds = {
  http_req_failed: ["rate<0.15"],
  http_req_duration: ["p(95)<30000"]
};
